import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/cooking/commands.md","filePath":"en/modules/cooking/commands.md","lastUpdated":0}`),a={name:`en/modules/cooking/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to “Commands and Permissions”">​</a></h1><p>The main command for EmakiCooking is <code>/ecooking</code>, alias <code>/ec</code>. Commands are used for help, reloading, inspecting held items or target blocks, rebuilding the station index, and debugging.</p><h2 id="command-list" tabindex="-1">Command list <a class="header-anchor" href="#command-list" aria-label="Permalink to “Command list”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/ec help</code></td><td><code>emakicooking.use</code></td><td>Show help.</td></tr><tr><td><code>/ec reload</code></td><td><code>emakicooking.reload</code> or <code>emakicooking.admin</code></td><td>Reload config, language, stations, recipes, GUI, and item adjustments.</td></tr><tr><td><code>/ec inspect hand</code></td><td><code>emakicooking.inspect</code>, <code>emakicooking.use</code>, or <code>emakicooking.admin</code></td><td>Inspect the held item source and cooking match status.</td></tr><tr><td><code>/ec inspect block</code></td><td><code>emakicooking.inspect</code>, <code>emakicooking.use</code>, or <code>emakicooking.admin</code></td><td>Inspect the target block within 6 blocks for station type, block state, TileState, PDC/YAML backend, and index status.</td></tr><tr><td><code>/ec station reindex</code></td><td><code>emakicooking.admin</code></td><td>Rebuild the station coordinate index from legacy YAML and currently loaded PDC stations.</td></tr><tr><td><code>/ec convert-legacy [confirm]</code></td><td><code>emakicooking.admin</code></td><td>Migrates old flat matcher keys to sibling <code>item_sources</code> + <code>matcher</code> fields or nested role nodes; fermentation-barrel <code>inputs[]</code> retains its legacy key for persisted slot-identity compatibility. Without an argument it performs a dry run; <code>confirm</code> (or <code>--apply</code>) writes files and keeps a backup.</td></tr><tr><td><code>/ec debug [status|on|off|player &lt;player&gt;|module &lt;module&gt;]</code></td><td><code>emakicooking.debug</code> or <code>emakicooking.admin</code></td><td>Output runtime debug information, see the subcommands below.</td></tr></tbody></table><h2 id="nutrition-commands" tabindex="-1">Nutrition commands <a class="header-anchor" href="#nutrition-commands" aria-label="Permalink to “Nutrition commands”">​</a></h2><p><code>/ec nutrition</code> queries and manages player nutrition values. See <a href="./nutrition.html">Nutrition System</a> for the gameplay.</p><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/ec nutrition get [player] [type]</code></td><td><code>emakicooking.nutrition.use</code>, <code>emakicooking.nutrition.admin</code>, or <code>emakicooking.admin</code></td><td>Query nutrition values. Without a type it lists <code>value / max</code> for all types; with a type it returns the current value. The player can be omitted (defaults to self; the console must specify one).</td></tr><tr><td><code>/ec nutrition set &lt;player&gt; &lt;type&gt; &lt;value&gt;</code></td><td><code>emakicooking.nutrition.admin</code> or <code>emakicooking.admin</code></td><td>Set a player&#39;s nutrition value for a type.</td></tr><tr><td><code>/ec nutrition add &lt;player&gt; &lt;type&gt; &lt;value&gt;</code></td><td><code>emakicooking.nutrition.admin</code> or <code>emakicooking.admin</code></td><td>Add to a player&#39;s nutrition value for a type.</td></tr><tr><td><code>/ec nutrition remove &lt;player&gt; &lt;type&gt; &lt;value&gt;</code></td><td><code>emakicooking.nutrition.admin</code> or <code>emakicooking.admin</code></td><td>Subtract from a player&#39;s nutrition value for a type.</td></tr></tbody></table><ul><li><code>set</code>, <code>add</code>, and <code>remove</code> require all four arguments, the target player must be online, and the written value is clamped to the type&#39;s <code>min~max</code>.</li><li>When the nutrition system is disabled, nutrition commands report that it is disabled.</li></ul><h2 id="base-permissions" tabindex="-1">Base permissions <a class="header-anchor" href="#base-permissions" aria-label="Permalink to “Base permissions”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakicooking.use</code></td><td>true</td><td>Basic usage permission.</td></tr><tr><td><code>emakicooking.reload</code></td><td>op</td><td>Reload configuration.</td></tr><tr><td><code>emakicooking.inspect</code></td><td>op</td><td>Inspect items or stations.</td></tr><tr><td><code>emakicooking.admin</code></td><td>op</td><td>Admin permission.</td></tr><tr><td><code>emakicooking.debug</code></td><td>op</td><td>Debug permission.</td></tr></tbody></table><h2 id="station-permissions" tabindex="-1">Station permissions <a class="header-anchor" href="#station-permissions" aria-label="Permalink to “Station permissions”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakicooking.station.chopping_board.use</code></td><td>true</td><td>Use the chopping board.</td></tr><tr><td><code>emakicooking.station.chopping_board.cut</code></td><td>true</td><td>Perform cutting.</td></tr><tr><td><code>emakicooking.station.wok.use</code></td><td>true</td><td>Use the wok.</td></tr><tr><td><code>emakicooking.station.wok.stir</code></td><td>true</td><td>Stir fry.</td></tr><tr><td><code>emakicooking.station.wok.serve</code></td><td>true</td><td>Serve from wok.</td></tr><tr><td><code>emakicooking.station.grinder.use</code></td><td>true</td><td>Use the grinder.</td></tr><tr><td><code>emakicooking.station.steamer.use</code></td><td>true</td><td>Use the steamer.</td></tr><tr><td><code>emakicooking.station.steamer.fuel</code></td><td>true</td><td>Add fuel to steamer.</td></tr><tr><td><code>emakicooking.station.steamer.moisture</code></td><td>true</td><td>Add moisture to steamer.</td></tr><tr><td><code>emakicooking.station.oven.use</code></td><td>true</td><td>Use the oven.</td></tr><tr><td><code>emakicooking.station.oven.fuel</code></td><td>true</td><td>Add fuel to oven.</td></tr><tr><td><code>emakicooking.station.juicer.use</code></td><td>true</td><td>Use the juicer.</td></tr><tr><td><code>emakicooking.station.juicer.press</code></td><td>true</td><td>Press ingredients.</td></tr><tr><td><code>emakicooking.station.juicer.collect</code></td><td>true</td><td>Collect juice.</td></tr><tr><td><code>emakicooking.station.fermentation_barrel.use</code></td><td>true</td><td>Use the fermentation barrel.</td></tr><tr><td><code>emakicooking.station.fermentation_barrel.start</code></td><td>true</td><td>Start fermentation.</td></tr><tr><td><code>emakicooking.station.fermentation_barrel.collect</code></td><td>true</td><td>Collect fermentation result.</td></tr></tbody></table><h2 id="nutrition-permissions" tabindex="-1">Nutrition permissions <a class="header-anchor" href="#nutrition-permissions" aria-label="Permalink to “Nutrition permissions”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>emakicooking.nutrition.use</code></td><td>true</td><td>Query your own nutrition values (<code>/ec nutrition get</code>).</td></tr><tr><td><code>emakicooking.nutrition.admin</code></td><td>op</td><td>Set, add, or remove any player&#39;s nutrition values.</td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p><code>emakicooking.admin</code> overrides all nutrition operations.</p></div><h2 id="common-operations" tabindex="-1">Common operations <a class="header-anchor" href="#common-operations" aria-label="Permalink to “Common operations”">​</a></h2><h3 id="inspect-held-item" tabindex="-1">Inspect held item <a class="header-anchor" href="#inspect-held-item" aria-label="Permalink to “Inspect held item”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ec inspect hand</span></span></code></pre></div><p>Use this to confirm whether the held item is recognized as a recipe input, container, fuel, tool, or station block.</p><h3 id="inspect-target-station-block" tabindex="-1">Inspect target station block <a class="header-anchor" href="#inspect-target-station-block" aria-label="Permalink to “Inspect target station block”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ec inspect block</span></span></code></pre></div><p>Use this to inspect the target block within 6 blocks for station type, item source, <code>block_state</code>, <code>tile_state</code>, <code>storage_backend</code>, <code>pdc_state</code>, <code>indexed</code>, <code>index_backend</code>, and <code>legacy_yaml</code>. On servers with many stations, this confirms whether the anchor uses <code>BLOCK_PDC</code> and avoids standalone YAML-file IO.</p><h3 id="rebuild-station-coordinate-index" tabindex="-1">Rebuild station coordinate index <a class="header-anchor" href="#rebuild-station-coordinate-index" aria-label="Permalink to “Rebuild station coordinate index”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ec station reindex</span></span></code></pre></div><p>Use this to scan legacy YAML states and currently loaded PDC stations, rebuilding <code>data/stations/index/&lt;world&gt;.idx</code>. Run it after migrating old data, replacing block entities, or seeing stations fail to restore on ChunkLoad.</p><h3 id="reload-cooking-configuration" tabindex="-1">Reload cooking configuration <a class="header-anchor" href="#reload-cooking-configuration" aria-label="Permalink to “Reload cooking configuration”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ec reload</span></span></code></pre></div><p>After reloading, check console output. If new station blocks, GUI, or recipe directories were added, verify state persistence and interaction flow on a test server first.</p><h3 id="debug-runtime-state" tabindex="-1">Debug runtime state <a class="header-anchor" href="#debug-runtime-state" aria-label="Permalink to “Debug runtime state”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ec debug</span></span>
<span class="line"><span>/ec debug status</span></span>
<span class="line"><span>/ec debug on</span></span>
<span class="line"><span>/ec debug off</span></span>
<span class="line"><span>/ec debug player &lt;player&gt;</span></span>
<span class="line"><span>/ec debug module &lt;module&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th></tr></thead><tbody><tr><td>no argument / <code>status</code></td><td>Print the current debug switch, tracked players, and enabled modules.</td></tr><tr><td><code>on</code> / <code>off</code></td><td>Enable or disable debug output globally.</td></tr><tr><td><code>player &lt;player&gt;</code></td><td>Toggle tracking for that online player; omitting the name lists the available modules.</td></tr><tr><td><code>module &lt;module&gt;</code></td><td>Toggle debug output for a single module. Modules available in EmakiCooking: <code>recipe</code>, <code>stir</code>, <code>display</code>, <code>station</code>, <code>pdc</code> (plus the shared CoreLib modules).</td></tr></tbody></table><p>An unrecognized subcommand falls back to printing the status. Useful for troubleshooting station listeners, display entities, recipe matching, and persistence state.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><ul><li>Station not working: check block source, station permissions, and interaction type.</li><li>Station state/backend unclear: run <code>/ec inspect block</code> and check <code>tile_state</code>, <code>storage_backend</code>, <code>pdc_state</code>, <code>indexed</code>, and <code>legacy_yaml</code>.</li><li>Station missing after restart or chunk load: run <code>/ec station reindex</code>, then check console for <code>lost_block_entity_replaced</code> or mismatch reports.</li><li>Materials cannot be placed: check <code>input_rules.only_recipe_items</code>, recipe directory, and item source.</li><li>Juicer cannot collect: check fluid capacity vs container <code>serving_ml</code>, and confirm <code>emakicooking.station.juicer.collect</code> permission.</li><li>Fermentation barrel cannot start: check input matches recipe and <code>start</code> permission.</li><li>Oven not progressing: check heat is within recipe range and fuel is effective.</li></ul>`,34)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};